sys_script.script:
(function executeRule(current, previous) {

    function normalize(value) {

        return (
            value || ''
        )
        .toString()
        .toLowerCase()
        .trim();

    }


    var service =
        new CampusMatchNotificationService();


    var matchId =
        current.getUniqueValue();


    var score =
        parseFloat(
            current.getValue(
                'overall_score'
            )
        );


    if (isNaN(score)) {
        return;
    }


    var status =
        normalize(
            current.getValue(
                'status'
            )
        );


    if (
        status === 'no_match' ||
        status === 'rejected' ||
        status === 'resolved' ||
        status === 'withdrawn'
    ) {
        return;
    }


    /* =========================================
       POTENTIAL MATCH
       Score 65 to below 80
    ========================================= */

    if (
        score >= 65 &&
        score < 80
    ) {

        var reviewed = false;


        if (
            current.isValidField('reviewed_by') &&
            current.getValue('reviewed_by')
        ) {

            reviewed = true;

        }


        if (
            current.isValidField('reviewed_on') &&
            current.getValue('reviewed_on')
        ) {

            reviewed = true;

        }


        if (!reviewed) {

            service.notifyAdmins(
                'Potential match requires review',
                'A Potential Match needs staff approval before ownership verification can continue.',
                '?id=campusmatch_admin_review&match_id=' +
                    matchId,
                'match',
                current.getTableName(),
                matchId,
                'potential_review:' +
                    matchId,
                'CampusMatch - Potential Match Review'
            );

        }

    }


    /* =========================================
       MULTIPLE STRONG MATCHES
       Score >= 80
    ========================================= */

    if (
        score >= 80
    ) {

        var foundId =
            current.getValue(
                'found_item'
            );


        if (
            !foundId &&
            current.isValidField(
                'u_found_item'
            )
        ) {

            foundId =
                current.getValue(
                    'u_found_item'
                );

        }


        if (!foundId) {
            return;
        }


        var strongCount = 0;


        var match =
            new GlideRecord(
                current.getTableName()
            );


        if (
            match.isValidField(
                'found_item'
            )
        ) {

            match.addQuery(
                'found_item',
                foundId
            );

        }
        else {

            match.addQuery(
                'u_found_item',
                foundId
            );

        }


        match.addQuery(
            'overall_score',
            '>=',
            80
        );


        match.query();


        while (
            match.next()
        ) {

            var candidateStatus =
                normalize(
                    match.getValue(
                        'status'
                    )
                );


            if (
                candidateStatus === 'no_match' ||
                candidateStatus === 'rejected' ||
                candidateStatus === 'resolved' ||
                candidateStatus === 'withdrawn'
            ) {

                continue;

            }


            strongCount++;

        }


        if (
            strongCount >= 2
        ) {

            service.notifyAdmins(
                'Multiple strong matches detected',
                strongCount +
                    ' Strong Match candidates currently exist for the same Found item.',
                '?id=campusmatch_admin_review&match_id=' +
                    matchId,
                'match',
                current.getTableName(),
                matchId,
                'multi_strong:' +
                    foundId +
                    ':' +
                    matchId,
                'CampusMatch - Multiple Strong Matches'
            );

        }

    }

})(
    current,
    previous
);
